@Component("mRPRun-handler")
@ProcessingGroup("mRPRun-processing-group")
public class MRPRunEventHandler {
	
	// core constructor
	MRPRunEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateMRPRunEvent
     */
    @EventHandler
    public void handle( CreateMRPRunEvent event) {
        entityManager.persist(new MRPRun(event.getMRPRunId(), event.getRunNumber(), event.getRunDateTime(), event.getPlanningHorizonDays(), event.getPlant(), event.getPlannedOrders(), event.getStatus()));
    }

    /*
     * @param	event UpdateMRPRunEvent
     */
    @EventHandler
    public MRPRun handle( UpdateMRPRunEvent event) {
    	entityManager.merge(new MRPRun(event.getMRPRunId(), event.getRunNumber(), event.getRunDateTime(), event.getPlanningHorizonDays(), event.getPlant(), event.getPlannedOrders(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteMRPRunEvent
     */
    @EventHandler
    public void on( DeleteMRPRunEvent event) {
    	MRPRun entity = new MRPRun();
   
    	// ------------------------------------------
    	// apply the MRPRunId
    	// ------------------------------------------
    	entity.setMRPRunId( event.getMRPRunId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final MRPRunRepository mRPRunEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(MRPRunEventHandler.class.getName());

}
